INSERT INTO public.obligacion_reglas(catalogo_id,version,tipo_control,origen_control,clasificacion_estado,normativa_estado,created_by,fuente_referencia,importacion_referencia)
SELECT c.id,1,m.tipo_control,'mixto','aprobada','pendiente',NULL,'Clasificación operativa; normativa y plazos por validar','plan-obligaciones-20261015'
FROM mapa m JOIN public.obligaciones_catalogo c ON c.id=m.catalogo_id AND c.programa=m.programa AND c.nombre=m.nombre
WHERE m.tipo_control IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.obligacion_reglas r WHERE r.catalogo_id=c.id)
ON CONFLICT DO NOTHING;
GRANT SELECT ON public.obligacion_reglas,public.obligacion_eventos,public.obligacion_revisiones,public.obligacion_relaciones TO service_role;
COMMIT;
